<script setup lang="ts">
import {leaveKind,type LeaveBalance} from '../complianceTypes'
defineProps<{balances:LeaveBalance[];english:boolean;companies?:{id:string;name:string}[]}>()
const operation=(v:string,en:boolean)=>( {use:en?'Leave used':'请假使用','cancel-use':en?'Cancellation reversal':'取消冲回',encash:en?'Encashed':'折现核销',adjust:en?'Reviewed adjustment':'人工调整',review:en?'Balance review':'余额复核','carry-out':en?'Carried to next year':'结转转出',expire:en?'Expired':'到期结清'} as Record<string,string>)[v]||v
</script>
<template><article v-for="b in balances" :key="b.account.id" class="wf-history"><p v-if="companies?.length" class="wf-muted">{{companies.find(c=>c.id===b.account.companyId)?.name||(english?'Previous employer':'历史雇主')}}</p><h3>{{leaveKind(b.account.kind,english)}} <small>{{b.account.unit==='day'?(english?'days':'天'):(english?'hours':'小时')}}</small></h3><dl class="wf-details"><dt>{{english?'Available':'可用'}}</dt><dd>{{b.available}}</dd><dt>{{english?'Reserved':'待批／待计薪占用'}}</dt><dd>{{b.reserved}}</dd><dt>{{english?'Used':'已使用'}}</dt><dd>{{b.used}}</dd><dt>{{english?'Encashed':'已正式折现'}}</dt><dd>{{b.encashed}}</dd><dt>{{english?'Accrued, not posted':'已累积待入账（已计入可用）'}}</dt><dd>{{b.dueAccrual}}</dd><dt>{{english?'Opening reconciled through':'期初对账截止'}}</dt><dd>{{b.account.openingOn}}</dd></dl><p v-if="b.account.kind==='hospital'" class="wf-hint">{{english?'This total includes outpatient sick leave. It is not an additional grant.':'病假合计包含门诊病假，不是额外再加一份额度。'}}</p><details><summary>{{english?'Credits, expiry and movements':'额度来源、到期及使用流水'}}</summary><div class="wf-table-wrap"><table><thead><tr><th>{{english?'Source':'来源'}}</th><th>{{english?'Granted':'额度'}}</th><th>{{english?'Remaining':'剩余'}}</th><th>{{english?'Reserved':'占用'}}</th><th>{{english?'Expiry':'到期日'}}</th></tr></thead><tbody><tr v-for="l in b.lots" :key="l.id"><td>{{({opening:english?'Opening':'期初核对',accrual:english?'Service accrual':'服务累积',carry:english?'Carryover':'上年结转',adjust:english?'Adjustment':'人工调整',review:english?'Review':'复核调整'} as Record<string,string>)[l.origin]||l.origin}}</td><td>{{l.quantity}}</td><td>{{l.remaining}}</td><td>{{l.reserved}}</td><td>{{l.expiresOn}}</td></tr></tbody></table></div><article v-for="entry in b.history" :key="entry.id" class="wf-history"><strong>{{operation(entry.operation,english)}} {{entry.quantity}}</strong><p>{{entry.reason}}</p><small>{{entry.createdAt}}</small></article></details></article></template>
